// Validate Meta Webhook Signature and Extract Payload
const body = items[0].json.body;
if (!body.entry || !body.entry[0].changes) {
  return [];
}

const change = body.entry[0].changes[0].value;
if (!change.messages || change.messages.length === 0) {
  return []; // Event is a status update, not a new message
}

const msg = change.messages[0];
const contact = change.contacts ? change.contacts[0] : {};

return [{
  json: {
    wa_id: msg.from,
    name: contact.profile ? contact.profile.name : 'WhatsApp Customer',
    content: msg.text ? msg.text.body : '[Media/Interactive]',
    type: msg.type,
    message_id: msg.id,
    timestamp: msg.timestamp
  }
}];

// Production & Mock Outbound Sender with Kill Switch Safety
const item = items[0].json;
const isKillSwitchActive = false; // Emergency Kill Switch (Set to true to halt outbound dispatch)

if (isKillSwitchActive) {
  return [{
    json: {
      dispatched: false,
      reason: 'KILL_SWITCH_ACTIVE',
      recipient: item.wa_id
    }
  }];
}

return [{
  json: {
    dispatched: true,
    recipient: item.wa_id,
    message_body: item.reply,
    requires_human: item.requires_human,
    provider: item.provider,
    model: item.model,
    confidence: item.confidence,
    reason: item.reason,
    timestamp: new Date().toISOString()
  }
}];
